function offsetMinutes(utcMs, timeZone) {
  const dtf = new Intl.DateTimeFormat('en-US', { timeZone, hour12: false,
    year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit' });
  const parts = dtf.formatToParts(new Date(utcMs));
  const o = {};
  for (const p of parts) o[p.type] = p.value;
  const asUTC = Date.UTC(+o.year, +o.month - 1, +o.day, +o.hour, +o.minute, +o.second);
  return (asUTC - utcMs) / 60000;
}
const summer = offsetMinutes(Date.UTC(2024, 0, 15, 12, 0, 0), 'Australia/Lord_Howe');
const winter = offsetMinutes(Date.UTC(2024, 6, 15, 12, 0, 0), 'Australia/Lord_Howe');
console.log('DST offset (min):', summer, '| standard offset (min):', winter, '| shift (min):', summer - winter);
